import './tag.css';
import template from './tag.hbs';
import Tag from './Tag.js';

const render = (args) => {
  const container = document.createElement('div');
  container.innerHTML = template(args);

  // Get the rendered element (root of the Handlebars component)
  const element = container.firstElementChild;

  // Initialize the Tag class for the rendered element
  if (element) {
    new Tag(element);
  } else {
    console.error("Failed to render the Handlebars template. Check the template or args.");
  }

  // Return the rendered DOM node
  return element;
};

export default {
  title: 'components/base/Tag',
  parameters: {
    layout: 'centered',
  },
  tags: ['autodocs'],
};

export const tag = {
  args: {
    text: 'some tag',
    hoverFill: false,
  },
  render,
};

export const highlight = {
  args: {
    text: 'some tag',
    highlight: true,
  },
  render,
};
